-- Migration: Create default team
-- Date: 2025-12-30
-- Description: Inserts a default team that can be used for all artifacts when no team is specified

-- Insert default team if it doesn't exist
-- Note: teams.id is now UUID (auto-generated by gen_random_uuid() default)
INSERT INTO public.teams (name, created_at, updated_at)
SELECT 'Default Team', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM public.teams WHERE name = 'Default Team'
);

